(()=>{const p={"N04-U08|pilot-serf:izdolshchina":{"category_id":"N04-U08","item_id":"pilot-serf:izdolshchina","question":"Чем издольщина отличается от отработок при общем основании аренды?","title":"Чем издольщина отличается от отработок при общем основании аренды?","text":"Общий критерий — способ арендной платы. При издольщине собственник земли получает установленную долю урожая; при отработках в сохранённом определении крестьянин обрабатывает помещичью землю собственным инвентарём. Сходство — использование арендованной земли и расчёт с её владельцем; различие — продуктовая доля либо труд. Определение издольщины само по себе не сообщает размер доли и не доказывает отсутствие личной свободы арендатора. Следовательно, форму платы, условия конкретного договора и личный статус следует устанавливать раздельно.","gap":"","coverage_status":"bounded_answer","official_category_exact":"Анализировать, сравнивать исторические события, явления, процессы.","existing_category_rule_exact":"Сравнение по общим критериям: сходства, различия и вывод. Рассматриваются, например, проекты разных групп помещиков, личная свобода и земельные ограничения, российское освобождение и зарубежные процессы.","source_learning_sha256":"dc60f87043c561b8f70519fde4fd7d744bbb38564db97b6b5c7cee9556a1b33f","source_item_sha256":"f1989e0cb08a42f2c0afa64df8e03c115c5064aefdd59990f430d617338a4b9b","source_provenance_sha256":"74234e98afe7498fb5daf1f36ac2d78acc339464f950703b8c019892f982b90b","source_paragraphs":[{"paragraph_1based":1,"text":"Издольщина — аренда земли, при которой собственник получает установленную долю урожая. Определяющий признак — форма арендной платы, а не отсутствие у арендатора личной свободы.","utf8_sha256":"940b5f1d5142702b2f788048b1cd4340bf3e388d9a5a754ddbce0e40478938e4"},{"paragraph_1based":2,"text":"При разборе пореформенной деревни этот термин нужно отличать от отработок: при издольщине расчёт выражен долей урожая, а в определении отработок источника — обработкой помещичьей земли собственным инвентарём. Название не сообщает само по себе ни размера доли, ни условий конкретного договора.","utf8_sha256":"aa00537427a8b91f4f4006cd49fff55f290986afdc388828669157e404bb7e72"}],"materials_reviewed":[{"source_url":"https://drive.google.com/file/d/1ZaCP9XcmpaeCBiEsT6ry-7hj5gIwIKBA/view?usp=drivesdk","page":11,"quote":"Издольщина – вид аренды земли, при которой арендная плата передается собственнику долей урожая.","quote_sha256":"edc9aa45fe30e2abd2d83e1bf3d74318add3afc9275c38fb1e8d038c0740712d","source_type":"reference","source_records":["reference-v19:page:73ef21fc-d5b5-513e-bc5e-af3e55ca868b:11"]}],"basis":["CARD_LEARNING.pilot-serf:izdolshchina.paragraphs","CARD_DATA.items.pilot-serf:izdolshchina.materials","CARD_LEARNING.pilot-serf:izdolshchina.sections"],"evidence_scope":"Приёмка конкретного ответа по сохранённому редакторскому материалу и приведённым фрагментам. Полные первоисточники, весь элемент и весь банк заданий заново не проверялись.","category_assignment_unchanged":true,"origin_colors_unchanged":true,"official_exam_key":false,"context_items":[{"item_id":"argument","source_learning_sha256":"9a990bcc57c61d3fe26ce5bd86a3f8a5a604c82d285cda4c97ef1ef777a6f322","source_item_sha256":"80a6845bde8aaf990c879b2f8dde82af1bd906732cd32013809a979f1a1e89ee"},{"item_id":"pilot-serf:izdolshchina","source_learning_sha256":"dc60f87043c561b8f70519fde4fd7d744bbb38564db97b6b5c7cee9556a1b33f","source_item_sha256":"f1989e0cb08a42f2c0afa64df8e03c115c5064aefdd59990f430d617338a4b9b"},{"item_id":"pilot-serf:january-1861","source_learning_sha256":"6ca84b3f8fd122643ae388b0e1a333c410083bb921e478dc930a3fb48ba4f947","source_item_sha256":"a0648bd2dc5429c990252b82648afae432ea8fc0601816bc296a7c74415611c7"},{"item_id":"pilot-serf:manifest-1861","source_learning_sha256":"ad55a1be086eaa54e281e351e5687d7c178e20eaa24ae30b107a1bb8dcb85697","source_item_sha256":"897d03bfefa4f2fbd7efa0d687adf0ccda6a889e956a21a76edd179ee6130fe6"},{"item_id":"pilot-serf:redemption-benefits","source_learning_sha256":"f5bf1e91fea60353f3d5b1b392e4b90c2c704c22e61c83a8f60be344e11785b6","source_item_sha256":"6df56536a5b63ca6b5d4d1ed7b4e31c327a2927257f1ab384234111cc0c09537"},{"item_id":"pilot-serf:significance","source_learning_sha256":"071a401902c6f0c012dd512d68cd610af34465c8a30036314bdd706b841dc948","source_item_sha256":"59675faca31349036a7413ae193c0edd006c7d9df6090f10b79ac5d2971b7890"},{"item_id":"pilot-serf:world-austria","source_learning_sha256":"bf9815155c3916384b0c63b9a87dcb2a9beebae61389ea30b790118da866395f","source_item_sha256":"076d4c01eedb6f0a50a5792e75eed180fccad34c983fa5240322d5e7d4475136"},{"item_id":"pilot-serf:year-1855","source_learning_sha256":"01a6cd7b48413011b454f7e6867f495182dabe087fc7b1498166ef2c01472db9","source_item_sha256":"6c8a4a69ae302b6ac5e06fb444f83ec6015f088f3f78d7712c10e48f26d7be74"},{"item_id":"pilot-serf:year-1857","source_learning_sha256":"7549ad551ac97259a9b660c209f999d7346c9ca7a324aa939b295dcbb5b98307","source_item_sha256":"e4965947efd70e361261a83aa5f82788191323a92a6f7ee5e30b99bd24adf87e"},{"item_id":"pilot-serf:year-1858","source_learning_sha256":"e09a80514ede19342b43a8957ee491284c5a6312adf301b3fc750c0c8a90e3d3","source_item_sha256":"5919b6e2a3ca67380107032d5d8893513f44caa6cd28f136da8664dbf53129c7"},{"item_id":"pilot-serf:year-1859","source_learning_sha256":"73c5287d4665ee1412e8abfa3b3bbaee5e07ec955913470cebc61165cfc3ef77","source_item_sha256":"bffd0b071513134af5ea81cca4d19e9999242ea33f509f36115b7c4211b76979"}],"source_sections":[],"additional_saved_quotes":[]},"N04-U08|pilot-serf:redemption-benefits":{"category_id":"N04-U08","item_id":"pilot-serf:redemption-benefits","question":"Как сравнить непосредственные результаты выкупа для помещика и крестьянина?","title":"Как сравнить непосредственные результаты выкупа для помещика и крестьянина?","text":"Критерии — получаемый ресурс и характер обязательства. Помещик получал выкупные средства, которые мог использовать на технику, наём работников, акции или вклад; удержание прежних государственных долгов могло уменьшать остающийся капитал. Для крестьянина переход на выкуп прекращал прежние повинности помещику и создавал обязанность погашать государственную ссуду в установленном порядке. В обычной схеме ссуды в 80% ежегодный выкупной платёж составлял 80% прежнего годового оброка; сравниваются именно годовые платежи, а не вся капитальная сумма с оброком. Обе стороны меняли экономические отношения, но получали разные результаты. Доступность капитала не доказывает всеобщей модернизации имений, а расчёт обычной схемы не универсален для всех сделок.","gap":"","coverage_status":"bounded_answer","official_category_exact":"Анализировать, сравнивать исторические события, явления, процессы.","existing_category_rule_exact":"Сравнение по общим критериям: сходства, различия и вывод. Рассматриваются, например, проекты разных групп помещиков, личная свобода и земельные ограничения, российское освобождение и зарубежные процессы.","source_learning_sha256":"f5bf1e91fea60353f3d5b1b392e4b90c2c704c22e61c83a8f60be344e11785b6","source_item_sha256":"6df56536a5b63ca6b5d4d1ed7b4e31c327a2927257f1ab384234111cc0c09537","source_provenance_sha256":"74234e98afe7498fb5daf1f36ac2d78acc339464f950703b8c019892f982b90b","source_paragraphs":[{"paragraph_1based":1,"text":"Выкуп давал помещикам капитал для модернизации; возможность модернизации не означает её всеобщего осуществления.","utf8_sha256":"ce9e8358ab955a27617f3adc97daf695e328c86f2fa7fd45e48ad2962da5fa79"},{"paragraph_1based":2,"text":"Получение капитала создавало возможность приобрести технику и нанять рабочую силу. Но возможность модернизации не тождественна её осуществлению: учебник отдельно отмечает трудности приспособления к новым условиям, сохранявшуюся сословность и слабость финансовых механизмов. Оценка реформы должна учитывать и предоставленные возможности, и ограничения их использования.","utf8_sha256":"7966a4640669603243a04473297b1ad48c918e2cf62c5d40fa15bccc9e96f64c"},{"paragraph_1based":3,"text":"Возможность использовать полученные средства на технику и наём работников была важна при переходе от зависимого труда к иным способам организации хозяйства. Однако результат зависел от того, как владелец распоряжался капиталом. Поэтому предоставление финансовой возможности и действительное хозяйственное обновление следует рассматривать как связанные, но не тождественные процессы.","utf8_sha256":"1fd2d7b3f37d40813c054e813c729b41ad3cb6c41ded28d1f889f973e41962e6"},{"paragraph_1based":4,"text":"Денежная компенсация создаёт ресурс для изменений, но сама по себе не показывает, как он был использован. Для модернизации требовалось изменить организацию хозяйства и труда; неразвитость финансовых механизмов затрудняла приспособление. Поэтому в ответе следует разделить непосредственный результат операции — получение средств — и возможное направление их применения. Это позволяет объяснить выгоду помещика без утверждения, будто все имения успешно перестроились.\n\nПри сопоставлении интересов сторон учебник отмечает, что после перехода на выкуп прекращались барщина и натуральные повинности помещику, а ежегодный выкупной платёж в обычной схеме ссуды в 80% был на 20% меньше прежнего годового оброка; это не сравнение всей выкупной суммы с годовым платежом. Выплата долга имела указанный срок, тогда как оброк характеризуется как бессрочный. Эти детали позволяют объяснить не только непосредственную денежную выгоду владельца, но и отличие нового обязательства для крестьянина.","utf8_sha256":"2cba258752564ba81a9f15ae999bbd2136d794e10508d85e706bfd552e1fa12f"},{"paragraph_1based":5,"text":"Получение выкупного капитала не означало одинаковой выгоды для всех помещиков. По учебнику, правительство удерживало задолженность перед государством при выдаче выкупа тем, кто прежде закладывал имения. Поэтому нужно различать начисленную сумму, удержанные долги и реально оставшиеся средства; возможность модернизации хозяйства зависела и от их последующего использования.","utf8_sha256":"b4d2b5285cca1c603747ce494c840df3bcfe850d698441a31bbc7728232308c3"},{"paragraph_1based":6,"text":"Помимо техники и найма работников, учебник называет возможность вложить полученные деньги в акции или поместить их в банк. Это перечень доступных направлений использования капитала; он не свидетельствует о том, что каждый помещик действительно выбрал одно из них или успешно модернизировал хозяйство.","utf8_sha256":"deb3c524aff0a6caf965140b222e4fe30755085a09828788a229788c3473d95b"}],"materials_reviewed":[{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":129,"quote":"они в ходе выкупной операции одномоментно получали крупные \nсуммы денег, которые могли потратить на закупку техники и наём рабо-\nчей силы для модернизации своего хозяйства","quote_sha256":"f46d2f67b801ba7955d97081dcacedfa95c89cf6099833ef5436d1e23810cc5d","source_type":"textbook","source_records":[]},{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":135,"quote":"правительство при выдаче выкупа удерживало задолженность","quote_sha256":"edf1b3ff3e3782b3cc43920556f6e6470c4c8358a79388592c6fcf8aa94c1dda","source_type":"textbook","source_records":[]}],"basis":["CARD_LEARNING.pilot-serf:redemption-benefits.paragraphs","CARD_DATA.items.pilot-serf:redemption-benefits.materials","CARD_LEARNING.pilot-serf:redemption-benefits.sections"],"evidence_scope":"Приёмка конкретного ответа по сохранённому редакторскому материалу и приведённым фрагментам. Полные первоисточники, весь элемент и весь банк заданий заново не проверялись.","category_assignment_unchanged":true,"origin_colors_unchanged":true,"official_exam_key":false,"context_items":[{"item_id":"argument","source_learning_sha256":"9a990bcc57c61d3fe26ce5bd86a3f8a5a604c82d285cda4c97ef1ef777a6f322","source_item_sha256":"80a6845bde8aaf990c879b2f8dde82af1bd906732cd32013809a979f1a1e89ee"},{"item_id":"pilot-serf:izdolshchina","source_learning_sha256":"dc60f87043c561b8f70519fde4fd7d744bbb38564db97b6b5c7cee9556a1b33f","source_item_sha256":"f1989e0cb08a42f2c0afa64df8e03c115c5064aefdd59990f430d617338a4b9b"},{"item_id":"pilot-serf:january-1861","source_learning_sha256":"6ca84b3f8fd122643ae388b0e1a333c410083bb921e478dc930a3fb48ba4f947","source_item_sha256":"a0648bd2dc5429c990252b82648afae432ea8fc0601816bc296a7c74415611c7"},{"item_id":"pilot-serf:manifest-1861","source_learning_sha256":"ad55a1be086eaa54e281e351e5687d7c178e20eaa24ae30b107a1bb8dcb85697","source_item_sha256":"897d03bfefa4f2fbd7efa0d687adf0ccda6a889e956a21a76edd179ee6130fe6"},{"item_id":"pilot-serf:redemption-benefits","source_learning_sha256":"f5bf1e91fea60353f3d5b1b392e4b90c2c704c22e61c83a8f60be344e11785b6","source_item_sha256":"6df56536a5b63ca6b5d4d1ed7b4e31c327a2927257f1ab384234111cc0c09537"},{"item_id":"pilot-serf:significance","source_learning_sha256":"071a401902c6f0c012dd512d68cd610af34465c8a30036314bdd706b841dc948","source_item_sha256":"59675faca31349036a7413ae193c0edd006c7d9df6090f10b79ac5d2971b7890"},{"item_id":"pilot-serf:world-austria","source_learning_sha256":"bf9815155c3916384b0c63b9a87dcb2a9beebae61389ea30b790118da866395f","source_item_sha256":"076d4c01eedb6f0a50a5792e75eed180fccad34c983fa5240322d5e7d4475136"},{"item_id":"pilot-serf:year-1855","source_learning_sha256":"01a6cd7b48413011b454f7e6867f495182dabe087fc7b1498166ef2c01472db9","source_item_sha256":"6c8a4a69ae302b6ac5e06fb444f83ec6015f088f3f78d7712c10e48f26d7be74"},{"item_id":"pilot-serf:year-1857","source_learning_sha256":"7549ad551ac97259a9b660c209f999d7346c9ca7a324aa939b295dcbb5b98307","source_item_sha256":"e4965947efd70e361261a83aa5f82788191323a92a6f7ee5e30b99bd24adf87e"},{"item_id":"pilot-serf:year-1858","source_learning_sha256":"e09a80514ede19342b43a8957ee491284c5a6312adf301b3fc750c0c8a90e3d3","source_item_sha256":"5919b6e2a3ca67380107032d5d8893513f44caa6cd28f136da8664dbf53129c7"},{"item_id":"pilot-serf:year-1859","source_learning_sha256":"73c5287d4665ee1412e8abfa3b3bbaee5e07ec955913470cebc61165cfc3ef77","source_item_sha256":"bffd0b071513134af5ea81cca4d19e9999242ea33f509f36115b7c4211b76979"}],"source_sections":[{"heading":"Средства для помещика","text":"Выкуп давал помещикам капитал для модернизации; возможность модернизации не означает её всеобщего осуществления.","utf8_sha256":"ce9e8358ab955a27617f3adc97daf695e328c86f2fa7fd45e48ad2962da5fa79"},{"heading":"Возможности и ограничения","text":"Получение капитала создавало возможность приобрести технику и нанять рабочую силу. Но возможность модернизации не тождественна её осуществлению: учебник отдельно отмечает трудности приспособления к новым условиям, сохранявшуюся сословность и слабость финансовых механизмов. Оценка реформы должна учитывать и предоставленные возможности, и ограничения их использования.","utf8_sha256":"7966a4640669603243a04473297b1ad48c918e2cf62c5d40fa15bccc9e96f64c"},{"heading":"Перестройка хозяйства","text":"Возможность использовать полученные средства на технику и наём работников была важна при переходе от зависимого труда к иным способам организации хозяйства. Однако результат зависел от того, как владелец распоряжался капиталом. Поэтому предоставление финансовой возможности и действительное хозяйственное обновление следует рассматривать как связанные, но не тождественные процессы.","utf8_sha256":"1fd2d7b3f37d40813c054e813c729b41ad3cb6c41ded28d1f889f973e41962e6"},{"heading":"Возможность и осуществлённый результат","text":"Денежная компенсация создаёт ресурс для изменений, но сама по себе не показывает, как он был использован. Для модернизации требовалось изменить организацию хозяйства и труда; неразвитость финансовых механизмов затрудняла приспособление. Поэтому в ответе следует разделить непосредственный результат операции — получение средств — и возможное направление их применения. Это позволяет объяснить выгоду помещика без утверждения, будто все имения успешно перестроились.\n\nПри сопоставлении интересов сторон учебник отмечает, что после перехода на выкуп прекращались барщина и натуральные повинности помещику, а ежегодный выкупной платёж в обычной схеме ссуды в 80% был на 20% меньше прежнего годового оброка; это не сравнение всей выкупной суммы с годовым платежом. Выплата долга имела указанный срок, тогда как оброк характеризуется как бессрочный. Эти детали позволяют объяснить не только непосредственную денежную выгоду владельца, но и отличие нового обязательства для крестьянина.","utf8_sha256":"2cba258752564ba81a9f15ae999bbd2136d794e10508d85e706bfd552e1fa12f"},{"heading":"Почему помещик не всегда получал всю сумму","text":"Получение выкупного капитала не означало одинаковой выгоды для всех помещиков. По учебнику, правительство удерживало задолженность перед государством при выдаче выкупа тем, кто прежде закладывал имения. Поэтому нужно различать начисленную сумму, удержанные долги и реально оставшиеся средства; возможность модернизации хозяйства зависела и от их последующего использования.","utf8_sha256":"b4d2b5285cca1c603747ce494c840df3bcfe850d698441a31bbc7728232308c3"},{"heading":"Другие направления использования капитала","text":"Помимо техники и найма работников, учебник называет возможность вложить полученные деньги в акции или поместить их в банк. Это перечень доступных направлений использования капитала; он не свидетельствует о том, что каждый помещик действительно выбрал одно из них или успешно модернизировал хозяйство.","utf8_sha256":"deb3c524aff0a6caf965140b222e4fe30755085a09828788a229788c3473d95b"},{"heading":"Основание расчёта и исключения","text":"Сравнивать с годовым оброком следует ежегодный выкупной платёж, а не всю капитальную сумму. В обычной схеме ссуды в 80% капитализированного оброка ежегодные 6% от этой ссуды давали 80% прежнего годового оброка. Это расчёт по указанной схеме, а не утверждение об одинаковых условиях каждой сделки. Исходное выражение учебника «выкупная сумма» сохранено только в цитате. Статья 66 предусматривала также ссуду в 75% при уменьшенном наделе, а статья 67 — особые случаи полной ссуды; поэтому расчёт не универсален.","utf8_sha256":"3be968bc5bcd5fe56b3ff26920509a59fb2d4ad8a7cb4edcb302b03cce3f9efb"}],"additional_saved_quotes":[]},"N04-U08|argument":{"category_id":"N04-U08","item_id":"argument","question":"Как сравнить интересы крестьян и помещиков по правовому и земельно-имущественному критериям?","title":"Как сравнить интересы крестьян и помещиков по правовому и земельно-имущественному критериям?","text":"По личному правовому положению крестьяне приобретали свободу, а помещики утрачивали собственность на человека и его труд. По земельно-имущественному критерию помещики получали выкупную компенсацию и отрезки; крестьяне приобретали землю через установленные условия выкупа, сохраняя до перехода на него повинности и сталкиваясь с недостаточностью наделов. Сходство — изменение положения обеих сторон; различие — содержание приобретений и потерь. Отсюда вывод о компромиссе: учёт имущественных интересов владельца не означает выгоды исключительно дворян, а личная свобода не устраняет земельных трудностей.","gap":"","coverage_status":"bounded_answer","official_category_exact":"Анализировать, сравнивать исторические события, явления, процессы.","existing_category_rule_exact":"Сравнение по общим критериям: сходства, различия и вывод. Рассматриваются, например, проекты разных групп помещиков, личная свобода и земельные ограничения, российское освобождение и зарубежные процессы.","source_learning_sha256":"9a990bcc57c61d3fe26ce5bd86a3f8a5a604c82d285cda4c97ef1ef777a6f322","source_item_sha256":"80a6845bde8aaf990c879b2f8dde82af1bd906732cd32013809a979f1a1e89ee","source_provenance_sha256":"74234e98afe7498fb5daf1f36ac2d78acc339464f950703b8c019892f982b90b","source_paragraphs":[{"paragraph_1based":1,"text":"В пользу тезиса об интересах дворян можно использовать условия земельной и выкупной операции. Помещики получали крупные суммы сразу; часть земли переходила к ним как отрезки. До перехода на выкуп временнообязанные крестьяне продолжали выполнять повинности.","utf8_sha256":"4cd35dae142bd6174ee50a7dade8414afdf9891b3cad1a5cf2e861a7d888a351"},{"paragraph_1based":2,"text":"Для возражения этому тезису подходят другие результаты: помещик утрачивал право собственности на крестьянина и его труд; крестьяне получали личную свободу и гражданские права. После перехода на выкуп прекращались барщина и натуральные повинности помещику; выкупные выплаты имели ограниченный срок, тогда как оброк был бессрочным.","utf8_sha256":"f8b085988d56d65b7466e01f8475fb2c57c275224a15d6cee84c3636fb336351"},{"paragraph_1based":3,"text":"Каждый аргумент должен соединять условие реформы с его последствием для конкретной группы. Учебник характеризует реформу как компромиссную: она меняла положение обеих сторон, сохраняя острые противоречия. Поэтому односторонняя оценка не раскрывает всех её результатов.","utf8_sha256":"f9488ba710cd72e2852e2bfd8e3c56d639c3d976a7aa6a5282db3b9617cadf5d"},{"paragraph_1based":4,"text":"Компромисс проявлялся в конкретных условиях: крестьяне получали личную свободу, помещики сохраняли значительную роль в земельных отношениях и получали выкупную компенсацию. При этом крестьяне не были удовлетворены наделами и повинностями, а помещики — всеми последствиями преобразования. Поэтому результат оценивается одновременно по достигнутым изменениям и сохранявшимся ограничениям.\n\nЗемля оставалась основой крестьянского хозяйства, поэтому уменьшение или недостаточность надела влияло на условия жизни независимо от полученных личных прав. Потребность в дополнительной земле могла вести к аренде у помещика. В пореформенной деревне такая аренда оплачивалась в том числе отработками, что сохраняло хозяйственную зависимость.","utf8_sha256":"5165f54ce2e29241714b0b33a198d5b51c021a45c736063222e0683e69c43b14"},{"paragraph_1based":5,"text":"Полный аргумент содержит положение, факт и объяснение связи между ними. Например, получение помещиком выкупных средств подтверждает учёт его имущественных интересов, поскольку передача земли сопровождалась компенсацией. Прекращение собственности на крестьянина подтверждает изменение в пользу личной самостоятельности, поскольку прежний владелец утрачивал власть над человеком как своим имуществом. Это два разных критерия оценки. Сопоставлять их нужно явно, иначе перечисление разнонаправленных условий выглядит противоречием, хотя именно оно раскрывает компромиссный характер преобразования.","utf8_sha256":"ce085f1d1c24d10ec6ef18d5e6cd1182ad7247b88e7e0914c7f498b8607fcec6"}],"materials_reviewed":[{"source_url":null,"page":128,"quote":"1 Манифест 1861 г. Личное освобождение крестьян. 19 февраля\n   1861  г. Александр II подписал Манифест о даровании крепостным лю-\n   дям прав состояния свободных сельских обывателей и «Положение о кре-\n   стьянах, выходящих из крепостной зависимости», включавшее 17 зако-\n   нодательных актов.\n     Реформа предусматривала, что крестьяне сразу получали личную сво-\n   боду, т. е. свободу перемещения, заключения брака, гражданских сделок,\n   торговли, перехода в другие сословия и т. д. (что ранее было возможно\n   только с согласия помещика).\n      Отменялась частная собственность на крестьянина и результаты его\n   труда, существовавшая на протяжении столетий. Крестьянин получил\n   право найма на работу как в деревне, так и в городах, возможность смены\n   места жительства и переезда из села в город, ведения собственного дела.","quote_sha256":"bfef05c1d33c7ca0d9bd2720047ec5cc201408f83913fa49baa0c9f745d547b0","source_type":null,"source_records":["4.6/04-P14/128/01","4.6/04-P14/128/02","4.6/04-P14/128/03"]},{"source_url":null,"page":128,"quote":"2 Крестьянские наделы и повинности. Крестьяне освобождались\n   с землёй, однако она не сразу переходила в их собственность. Свой надел\n   они должны были выкупить у помещика, по-прежнему работая на бар-\n  щине или выплачивая оброк. Размеры выкупа земли в каждом регионе\n   устанавливались разные. Государство оплачивало 80 % стоимости надела.\n   Эти деньги крестьяне должны были вернуть в течение 49 лет, ежегодно\n   выплачивая государству 6 % от полученной суммы (так называемые вы-\n   купные платежи). Однако не все крестьяне сразу же перешли на выкуп\n   земли, многие продолжали работать на помещика — таких крестьян на-\n   зывали временнообязанными. Лишь в 1881 г. был издан указ о переводе\n   всех временнообязанных крестьян на обязательный выкуп.","quote_sha256":"7377e0b389a71887a5a9b92ba62c9c965f9d24ab5e4f393a8e16c6c5ce85ba95","source_type":null,"source_records":["4.6/04-P14/128/01","4.6/04-P14/128/02","4.6/04-P14/128/03"]},{"source_url":null,"page":128,"quote":"В законе было указано, земельные наделы какого размера должны бы-\n   ли получить крестьяне в каждом регионе. Если крестьянин пользовался до\n   реформы 1861 г. наделом, размер которого был выше нормы, установлен-","quote_sha256":"4218b1cd4d524a41dea6bf45da23f4698ace27b684b843a5b8682fc91030399a","source_type":null,"source_records":["4.6/04-P14/128/01","4.6/04-P14/128/02","4.6/04-P14/128/03"]},{"source_url":null,"page":129,"quote":"ной для данной конкретной губернии,\nто он должен был вернуть помещику\n«лишние» земли (проводились так на-\nзываемые отрезки). Если же надел кре-\nстьянина имел размер ниже установ-\nленного, то помещик обязан был или\nприрезать недостающую землю, или снизить повинности. Отрезки встре-\nчались гораздо чаще, чем прирезки земли. В чернозёмных губерниях, где\nземля была плодородная и дорогая, размер земель, отрезанных от крестьян\nв пользу помещиков, доходил до 20 %. Для урегулирования возникавших\nземельных и имущественных споров между помещиками и крестьянской\nобщиной были учреждены специальные должности мировых посредников.\nНазначаемые из местных дворян, они вместе с сельскими старостами в те-\nчение двух лет должны были составить уставные грамоты, где обознача-\nлись условия сделки для каждой крестьянской общины.","quote_sha256":"649e884acbcac8df7a2bde684411a449665f4ed8de205d32c5e38c95a8463b71","source_type":null,"source_records":["4.6/04-P14/129/01","4.6/04-P14/129/02","4.6/04-P14/129/03"]},{"source_url":null,"page":129,"quote":"Для крестьян прекращались барщина и натуральные повинности по-\nмещику. Выкупная сумма была почти на 20 % меньше суммы оброка.\nВыкупная операция предполагала ограниченный срок выплаты долга\n(49 лет), а оброк был бессрочным. Выгода помещиков заключалась в том,\nчто они в ходе выкупной операции одномоментно получали крупные\nсуммы денег, которые могли потратить на закупку техники и наём рабо-\nчей силы для модернизации своего хозяйства. Капитал можно было вло-\nжить в акции или поместить в банк.","quote_sha256":"b4c019ca156b62e8e92e96c69d8cd93e07b6acd1d74f68c3bf43a8df872c9d43","source_type":null,"source_records":["4.6/04-P14/129/01","4.6/04-P14/129/02","4.6/04-P14/129/03"]},{"source_url":null,"page":130,"quote":"4 Значение Крестьянской реформы 1861 г. В результате отмены кре-\n   постной зависимости около 24 млн крестьян стали лично свободными.\n   Реформа открыла путь развитию новых экономических отношений, спо-\n   собствовала созданию рынка свободной рабочей силы.\n     Однако всех проблем реформа решить не могла. Сохранялись много-\n   численные пережитки крепостного права (временнообязанное состояние\n   крестьян). По сути, реформа не решила, а усугубила проблему малоземе-\n   лья крестьян.\n    В результате передачи отрезков помещикам крестьяне потеряли около\n   20 % своих прежних наделов. При этом теряли они, как правило, лучшие\n   земли: с лугами, выпасами, водопоями и т. д. Крестьяне, обязанные со-\n   вершать выкупные платежи, отныне выплачивали стоимость не только\n   земли, но и, по сути, тех доходов, которые теряли помещики, лишив-\n   шись крепостного труда.\n     Коренная по своему значению реформа по историческим меркам бы-\n   ла проведена довольно быстро: всего за 50 лет. Но большая часть тех,\n   кого она коснулась, т. е. дворян и крестьян, не была к ней в полной мере\n   готова. Большинство помещиков и после реформы не использовали тех-\n   нику, современные агрокультурные методы хозяйствования, не были\n   вовлечены в активные рыночные связи. Многие просто потратили день-\n   ги, полученные в ходе реформы. Крестьяне же были в массе своей негра-\n   мотны и бедны. Отсутствовала развитая финансовая система, например\n   кредитование, которое могло бы смягчить адаптацию участников рефор-\n  мы к новым условиям. Сохранялся сословный строй общества.\n    В целом же реформа носила компромиссный характер, поэтому недо-\n   вольных её результатами оказалось много как среди помещиков, так\n   и среди крестьян.","quote_sha256":"c23aa83d05c99b85932055769ee4f7c52befc4bbfe50e2757fb51a5ece046240","source_type":null,"source_records":["4.6/04-P14/130/01","4.6/04-P14/130/02","4.6/04-P14/130/03"]}],"basis":["CARD_LEARNING.argument.paragraphs","CARD_DATA.items.argument.materials","CARD_LEARNING.argument.sections"],"evidence_scope":"Приёмка конкретного ответа по сохранённому редакторскому материалу и приведённым фрагментам. Полные первоисточники, весь элемент и весь банк заданий заново не проверялись.","category_assignment_unchanged":true,"origin_colors_unchanged":true,"official_exam_key":false,"context_items":[{"item_id":"argument","source_learning_sha256":"9a990bcc57c61d3fe26ce5bd86a3f8a5a604c82d285cda4c97ef1ef777a6f322","source_item_sha256":"80a6845bde8aaf990c879b2f8dde82af1bd906732cd32013809a979f1a1e89ee"},{"item_id":"pilot-serf:izdolshchina","source_learning_sha256":"dc60f87043c561b8f70519fde4fd7d744bbb38564db97b6b5c7cee9556a1b33f","source_item_sha256":"f1989e0cb08a42f2c0afa64df8e03c115c5064aefdd59990f430d617338a4b9b"},{"item_id":"pilot-serf:january-1861","source_learning_sha256":"6ca84b3f8fd122643ae388b0e1a333c410083bb921e478dc930a3fb48ba4f947","source_item_sha256":"a0648bd2dc5429c990252b82648afae432ea8fc0601816bc296a7c74415611c7"},{"item_id":"pilot-serf:manifest-1861","source_learning_sha256":"ad55a1be086eaa54e281e351e5687d7c178e20eaa24ae30b107a1bb8dcb85697","source_item_sha256":"897d03bfefa4f2fbd7efa0d687adf0ccda6a889e956a21a76edd179ee6130fe6"},{"item_id":"pilot-serf:redemption-benefits","source_learning_sha256":"f5bf1e91fea60353f3d5b1b392e4b90c2c704c22e61c83a8f60be344e11785b6","source_item_sha256":"6df56536a5b63ca6b5d4d1ed7b4e31c327a2927257f1ab384234111cc0c09537"},{"item_id":"pilot-serf:significance","source_learning_sha256":"071a401902c6f0c012dd512d68cd610af34465c8a30036314bdd706b841dc948","source_item_sha256":"59675faca31349036a7413ae193c0edd006c7d9df6090f10b79ac5d2971b7890"},{"item_id":"pilot-serf:world-austria","source_learning_sha256":"bf9815155c3916384b0c63b9a87dcb2a9beebae61389ea30b790118da866395f","source_item_sha256":"076d4c01eedb6f0a50a5792e75eed180fccad34c983fa5240322d5e7d4475136"},{"item_id":"pilot-serf:year-1855","source_learning_sha256":"01a6cd7b48413011b454f7e6867f495182dabe087fc7b1498166ef2c01472db9","source_item_sha256":"6c8a4a69ae302b6ac5e06fb444f83ec6015f088f3f78d7712c10e48f26d7be74"},{"item_id":"pilot-serf:year-1857","source_learning_sha256":"7549ad551ac97259a9b660c209f999d7346c9ca7a324aa939b295dcbb5b98307","source_item_sha256":"e4965947efd70e361261a83aa5f82788191323a92a6f7ee5e30b99bd24adf87e"},{"item_id":"pilot-serf:year-1858","source_learning_sha256":"e09a80514ede19342b43a8957ee491284c5a6312adf301b3fc750c0c8a90e3d3","source_item_sha256":"5919b6e2a3ca67380107032d5d8893513f44caa6cd28f136da8664dbf53129c7"},{"item_id":"pilot-serf:year-1859","source_learning_sha256":"73c5287d4665ee1412e8abfa3b3bbaee5e07ec955913470cebc61165cfc3ef77","source_item_sha256":"bffd0b071513134af5ea81cca4d19e9999242ea33f509f36115b7c4211b76979"}],"source_sections":[{"heading":"Интересы помещиков","text":"В пользу тезиса об интересах дворян можно использовать условия земельной и выкупной операции. Помещики получали крупные суммы сразу; часть земли переходила к ним как отрезки. До перехода на выкуп временнообязанные крестьяне продолжали выполнять повинности.","utf8_sha256":"4cd35dae142bd6174ee50a7dade8414afdf9891b3cad1a5cf2e861a7d888a351"},{"heading":"Изменения в пользу крестьян","text":"Для возражения этому тезису подходят другие результаты: помещик утрачивал право собственности на крестьянина и его труд; крестьяне получали личную свободу и гражданские права. После перехода на выкуп прекращались барщина и натуральные повинности помещику; выкупные выплаты имели ограниченный срок, тогда как оброк был бессрочным.","utf8_sha256":"f8b085988d56d65b7466e01f8475fb2c57c275224a15d6cee84c3636fb336351"},{"heading":"Как обосновать оценку","text":"Каждый аргумент должен соединять условие реформы с его последствием для конкретной группы. Учебник характеризует реформу как компромиссную: она меняла положение обеих сторон, сохраняя острые противоречия. Поэтому односторонняя оценка не раскрывает всех её результатов.","utf8_sha256":"f9488ba710cd72e2852e2bfd8e3c56d639c3d976a7aa6a5282db3b9617cadf5d"},{"heading":"Компромисс и земельные последствия","text":"Компромисс проявлялся в конкретных условиях: крестьяне получали личную свободу, помещики сохраняли значительную роль в земельных отношениях и получали выкупную компенсацию. При этом крестьяне не были удовлетворены наделами и повинностями, а помещики — всеми последствиями преобразования. Поэтому результат оценивается одновременно по достигнутым изменениям и сохранявшимся ограничениям.\n\nЗемля оставалась основой крестьянского хозяйства, поэтому уменьшение или недостаточность надела влияло на условия жизни независимо от полученных личных прав. Потребность в дополнительной земле могла вести к аренде у помещика. В пореформенной деревне такая аренда оплачивалась в том числе отработками, что сохраняло хозяйственную зависимость.","utf8_sha256":"5165f54ce2e29241714b0b33a198d5b51c021a45c736063222e0683e69c43b14"},{"heading":"Как устроен аргумент","text":"Полный аргумент содержит положение, факт и объяснение связи между ними. Например, получение помещиком выкупных средств подтверждает учёт его имущественных интересов, поскольку передача земли сопровождалась компенсацией. Прекращение собственности на крестьянина подтверждает изменение в пользу личной самостоятельности, поскольку прежний владелец утрачивал власть над человеком как своим имуществом. Это два разных критерия оценки. Сопоставлять их нужно явно, иначе перечисление разнонаправленных условий выглядит противоречием, хотя именно оно раскрывает компромиссный характер преобразования.","utf8_sha256":"ce085f1d1c24d10ec6ef18d5e6cd1182ad7247b88e7e0914c7f498b8607fcec6"}],"additional_saved_quotes":[]},"N04-U08|pilot-serf:significance":{"category_id":"N04-U08","item_id":"pilot-serf:significance","question":"Как сопоставить достижения и ограничения реформы по одинаковым сферам?","title":"Как сопоставить достижения и ограничения реформы по одинаковым сферам?","text":"Критерии — правовое положение и хозяйственные возможности. В правовой сфере достижение состояло в прекращении собственности помещика на крестьянина; сохранявшийся сословный строй ограничивал глубину преобразования. В хозяйственной сфере расширялись условия свободного найма и самостоятельности, но малоземелье, выкуп и переходные повинности затрудняли реализацию возможностей. Сопоставление показывает сочетание перемен и ограничений в каждой сфере. Поэтому недовольство участников не отменяет исторического значения личного освобождения, а значение освобождения не доказывает отсутствия экономических проблем. Так раскрывается компромиссный характер реформы.","gap":"","coverage_status":"bounded_answer","official_category_exact":"Анализировать, сравнивать исторические события, явления, процессы.","existing_category_rule_exact":"Сравнение по общим критериям: сходства, различия и вывод. Рассматриваются, например, проекты разных групп помещиков, личная свобода и земельные ограничения, российское освобождение и зарубежные процессы.","source_learning_sha256":"071a401902c6f0c012dd512d68cd610af34465c8a30036314bdd706b841dc948","source_item_sha256":"59675faca31349036a7413ae193c0edd006c7d9df6090f10b79ac5d2971b7890","source_provenance_sha256":"74234e98afe7498fb5daf1f36ac2d78acc339464f950703b8c019892f982b90b","source_paragraphs":[{"paragraph_1based":1,"text":"Реформа сочетала крупное преобразование с ограничениями и вызвала недовольство обеих сторон.","utf8_sha256":"1a0b8eae70df56a0a945074f19753ef7dda9be92cac4e1c9e1d5a040c99758aa"},{"paragraph_1based":2,"text":"Положительный результат — развитие новых экономических отношений и рынка труда — сочетался с малоземельем и сохранявшимися ограничениями. Поэтому оценка реформы не сводится ни к перечислению полученных прав, ни к одному перечню недостатков. Компромиссный характер проявлялся в сочетании преобразований с условиями, вызывавшими недовольство разных сторон.","utf8_sha256":"3152f0d9a90fb81eb40ad4b03f058e1f4374bd8297af0bb119d7b6e80080c82f"},{"paragraph_1based":3,"text":"Компромисс проявлялся в конкретных условиях: крестьяне получали личную свободу, помещики сохраняли значительную роль в земельных отношениях и получали выкупную компенсацию. При этом крестьяне не были удовлетворены наделами и повинностями, а помещики — всеми последствиями преобразования. Поэтому результат оценивается одновременно по достигнутым изменениям и сохранявшимся ограничениям.","utf8_sha256":"db4c0e03b8bcda2e08dba8294fd47520c120d5496c3c2ac68760c89c11660598"},{"paragraph_1based":4,"text":"Обоснованная оценка соединяет конкретный результат с его значением. Прекращение собственности на человека расширяло личную самостоятельность; выкуп и земельные ограничения осложняли хозяйственное положение. Эти стороны нельзя взаимно исключать: недостатки условий не отменяют освобождения, а освобождение не доказывает отсутствия недостатков. Именно сопоставление правового изменения с материальными условиями объясняет и исторический масштаб реформы, и недовольство участников.","utf8_sha256":"b8d0c5c55cfbc1fb25d8ed48150771d451c95b4ab4656b18bd5ca1f79b00c19f"}],"materials_reviewed":[{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":130,"quote":"В целом же реформа носила компромиссный характер, поэтому недо-\nвольных её результатами оказалось много как среди помещиков, так \nи среди крестьян","quote_sha256":"71ea9b1fc284e0409d7b7fe0d25fd008295295f2160bc21d1b3a6519aab8d596","source_type":"textbook","source_records":[]}],"basis":["CARD_LEARNING.pilot-serf:significance.paragraphs","CARD_DATA.items.pilot-serf:significance.materials","CARD_LEARNING.pilot-serf:significance.sections"],"evidence_scope":"Приёмка конкретного ответа по сохранённому редакторскому материалу и приведённым фрагментам. Полные первоисточники, весь элемент и весь банк заданий заново не проверялись.","category_assignment_unchanged":true,"origin_colors_unchanged":true,"official_exam_key":false,"context_items":[{"item_id":"argument","source_learning_sha256":"9a990bcc57c61d3fe26ce5bd86a3f8a5a604c82d285cda4c97ef1ef777a6f322","source_item_sha256":"80a6845bde8aaf990c879b2f8dde82af1bd906732cd32013809a979f1a1e89ee"},{"item_id":"pilot-serf:izdolshchina","source_learning_sha256":"dc60f87043c561b8f70519fde4fd7d744bbb38564db97b6b5c7cee9556a1b33f","source_item_sha256":"f1989e0cb08a42f2c0afa64df8e03c115c5064aefdd59990f430d617338a4b9b"},{"item_id":"pilot-serf:january-1861","source_learning_sha256":"6ca84b3f8fd122643ae388b0e1a333c410083bb921e478dc930a3fb48ba4f947","source_item_sha256":"a0648bd2dc5429c990252b82648afae432ea8fc0601816bc296a7c74415611c7"},{"item_id":"pilot-serf:manifest-1861","source_learning_sha256":"ad55a1be086eaa54e281e351e5687d7c178e20eaa24ae30b107a1bb8dcb85697","source_item_sha256":"897d03bfefa4f2fbd7efa0d687adf0ccda6a889e956a21a76edd179ee6130fe6"},{"item_id":"pilot-serf:redemption-benefits","source_learning_sha256":"f5bf1e91fea60353f3d5b1b392e4b90c2c704c22e61c83a8f60be344e11785b6","source_item_sha256":"6df56536a5b63ca6b5d4d1ed7b4e31c327a2927257f1ab384234111cc0c09537"},{"item_id":"pilot-serf:significance","source_learning_sha256":"071a401902c6f0c012dd512d68cd610af34465c8a30036314bdd706b841dc948","source_item_sha256":"59675faca31349036a7413ae193c0edd006c7d9df6090f10b79ac5d2971b7890"},{"item_id":"pilot-serf:world-austria","source_learning_sha256":"bf9815155c3916384b0c63b9a87dcb2a9beebae61389ea30b790118da866395f","source_item_sha256":"076d4c01eedb6f0a50a5792e75eed180fccad34c983fa5240322d5e7d4475136"},{"item_id":"pilot-serf:year-1855","source_learning_sha256":"01a6cd7b48413011b454f7e6867f495182dabe087fc7b1498166ef2c01472db9","source_item_sha256":"6c8a4a69ae302b6ac5e06fb444f83ec6015f088f3f78d7712c10e48f26d7be74"},{"item_id":"pilot-serf:year-1857","source_learning_sha256":"7549ad551ac97259a9b660c209f999d7346c9ca7a324aa939b295dcbb5b98307","source_item_sha256":"e4965947efd70e361261a83aa5f82788191323a92a6f7ee5e30b99bd24adf87e"},{"item_id":"pilot-serf:year-1858","source_learning_sha256":"e09a80514ede19342b43a8957ee491284c5a6312adf301b3fc750c0c8a90e3d3","source_item_sha256":"5919b6e2a3ca67380107032d5d8893513f44caa6cd28f136da8664dbf53129c7"},{"item_id":"pilot-serf:year-1859","source_learning_sha256":"73c5287d4665ee1412e8abfa3b3bbaee5e07ec955913470cebc61165cfc3ef77","source_item_sha256":"bffd0b071513134af5ea81cca4d19e9999242ea33f509f36115b7c4211b76979"}],"source_sections":[{"heading":"Главный результат и ограничения","text":"Реформа сочетала крупное преобразование с ограничениями и вызвала недовольство обеих сторон.","utf8_sha256":"1a0b8eae70df56a0a945074f19753ef7dda9be92cac4e1c9e1d5a040c99758aa"},{"heading":"Две стороны преобразования","text":"Положительный результат — развитие новых экономических отношений и рынка труда — сочетался с малоземельем и сохранявшимися ограничениями. Поэтому оценка реформы не сводится ни к перечислению полученных прав, ни к одному перечню недостатков. Компромиссный характер проявлялся в сочетании преобразований с условиями, вызывавшими недовольство разных сторон.","utf8_sha256":"3152f0d9a90fb81eb40ad4b03f058e1f4374bd8297af0bb119d7b6e80080c82f"},{"heading":"Компромисс интересов","text":"Компромисс проявлялся в конкретных условиях: крестьяне получали личную свободу, помещики сохраняли значительную роль в земельных отношениях и получали выкупную компенсацию. При этом крестьяне не были удовлетворены наделами и повинностями, а помещики — всеми последствиями преобразования. Поэтому результат оценивается одновременно по достигнутым изменениям и сохранявшимся ограничениям.","utf8_sha256":"db4c0e03b8bcda2e08dba8294fd47520c120d5496c3c2ac68760c89c11660598"},{"heading":"Как обосновать оценку реформы","text":"Обоснованная оценка соединяет конкретный результат с его значением. Прекращение собственности на человека расширяло личную самостоятельность; выкуп и земельные ограничения осложняли хозяйственное положение. Эти стороны нельзя взаимно исключать: недостатки условий не отменяют освобождения, а освобождение не доказывает отсутствия недостатков. Именно сопоставление правового изменения с материальными условиями объясняет и исторический масштаб реформы, и недовольство участников.","utf8_sha256":"b8d0c5c55cfbc1fb25d8ed48150771d451c95b4ab4656b18bd5ca1f79b00c19f"}],"additional_saved_quotes":[]},"N04-U08|pilot-serf:world-austria":{"category_id":"N04-U08","item_id":"pilot-serf:world-austria","question":"Как сравнить австрийские преобразования 1848 года с российской реформой 1861 года по трём признакам?","title":"Как сравнить австрийские преобразования 1848 года с российской реформой 1861 года по трём признакам?","text":"Критерии — личное положение, земельные повинности и государственное финансирование. Общее направление — устранение личной зависимости при преобразовании земельных отношений, хотя исходный статус крестьян разных австрийских земель различался. По австрийскому закону отменялись повинности, причём требования различались по наличию компенсации; в России временнообязанные после личного освобождения сохраняли повинности до выкупа. В сопоставленной австрийской схеме капитализированной суммы повинностей треть списывалась, треть платил крестьянин, треть — государство. Российская государственная ссуда подлежала возврату крестьянами. Следовательно, сроки, переходные обязанности и форма помощи отличались. Австрийскую схему нельзя без оговорок переносить на всю империю или называть её оценкой рыночной стоимости земли: отдельно учитываются венгерские меры и региональные различия.","gap":"","coverage_status":"bounded_answer","official_category_exact":"Анализировать, сравнивать исторические события, явления, процессы.","existing_category_rule_exact":"Сравнение по общим критериям: сходства, различия и вывод. Рассматриваются, например, проекты разных групп помещиков, личная свобода и земельные ограничения, российское освобождение и зарубежные процессы.","source_learning_sha256":"bf9815155c3916384b0c63b9a87dcb2a9beebae61389ea30b790118da866395f","source_item_sha256":"076d4c01eedb6f0a50a5792e75eed180fccad34c983fa5240322d5e7d4475136","source_provenance_sha256":"74234e98afe7498fb5daf1f36ac2d78acc339464f950703b8c019892f982b90b","source_paragraphs":[{"paragraph_1based":1,"text":"В блоке «В это время в мире» окончательная отмена крепостного права в Австрийской империи отнесена к середине XIX века. Источник задаёт период, а не точную дату; в этой карточке он сохранён без произвольного уточнения года.","utf8_sha256":"5022d83b134507d76c7692f9ae153aca97786c44ec161533338330b0f099104b"},{"paragraph_1based":2,"text":"Российская реформа 1861 года входит в тот же широкий исторический процесс изменения личного положения зависимого населения. Сопоставление показывает, что проблема крепостной зависимости не была исключительно российской.","utf8_sha256":"007372f31b839d23ba607af1f94a2e00c86a16f5b2b8ef947c213a0c2da2c9c9"},{"paragraph_1based":3,"text":"Из близости времени нельзя вывести одинаковость реформ. Для сравнения условий освобождения потребовались бы сведения о земле, повинностях, компенсациях и государственном устройстве каждой страны. Здесь проверяется знание международного контекста, а не тождество механизмов реформ.","utf8_sha256":"b60197df7c6fd12927cf4f3ac734fa185451cb06c14f4f6678464116e65caa84"}],"materials_reviewed":[{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":123,"quote":"Крепостное право лишь в середине XIX в. было окончательно отменено в Австрийской империи","quote_sha256":"eb656d4e6a899132bbd6c6cbc34c266cff10d4299bb13284a86a215249838906","source_type":"textbook","source_records":[]}],"basis":["CARD_LEARNING.pilot-serf:world-austria.paragraphs","CARD_DATA.items.pilot-serf:world-austria.materials","CARD_LEARNING.pilot-serf:world-austria.sections"],"evidence_scope":"Приёмка конкретного ответа по сохранённому редакторскому материалу и приведённым фрагментам. Полные первоисточники, весь элемент и весь банк заданий заново не проверялись.","category_assignment_unchanged":true,"origin_colors_unchanged":true,"official_exam_key":false,"context_items":[{"item_id":"argument","source_learning_sha256":"9a990bcc57c61d3fe26ce5bd86a3f8a5a604c82d285cda4c97ef1ef777a6f322","source_item_sha256":"80a6845bde8aaf990c879b2f8dde82af1bd906732cd32013809a979f1a1e89ee"},{"item_id":"pilot-serf:izdolshchina","source_learning_sha256":"dc60f87043c561b8f70519fde4fd7d744bbb38564db97b6b5c7cee9556a1b33f","source_item_sha256":"f1989e0cb08a42f2c0afa64df8e03c115c5064aefdd59990f430d617338a4b9b"},{"item_id":"pilot-serf:january-1861","source_learning_sha256":"6ca84b3f8fd122643ae388b0e1a333c410083bb921e478dc930a3fb48ba4f947","source_item_sha256":"a0648bd2dc5429c990252b82648afae432ea8fc0601816bc296a7c74415611c7"},{"item_id":"pilot-serf:manifest-1861","source_learning_sha256":"ad55a1be086eaa54e281e351e5687d7c178e20eaa24ae30b107a1bb8dcb85697","source_item_sha256":"897d03bfefa4f2fbd7efa0d687adf0ccda6a889e956a21a76edd179ee6130fe6"},{"item_id":"pilot-serf:redemption-benefits","source_learning_sha256":"f5bf1e91fea60353f3d5b1b392e4b90c2c704c22e61c83a8f60be344e11785b6","source_item_sha256":"6df56536a5b63ca6b5d4d1ed7b4e31c327a2927257f1ab384234111cc0c09537"},{"item_id":"pilot-serf:significance","source_learning_sha256":"071a401902c6f0c012dd512d68cd610af34465c8a30036314bdd706b841dc948","source_item_sha256":"59675faca31349036a7413ae193c0edd006c7d9df6090f10b79ac5d2971b7890"},{"item_id":"pilot-serf:world-austria","source_learning_sha256":"bf9815155c3916384b0c63b9a87dcb2a9beebae61389ea30b790118da866395f","source_item_sha256":"076d4c01eedb6f0a50a5792e75eed180fccad34c983fa5240322d5e7d4475136"},{"item_id":"pilot-serf:year-1855","source_learning_sha256":"01a6cd7b48413011b454f7e6867f495182dabe087fc7b1498166ef2c01472db9","source_item_sha256":"6c8a4a69ae302b6ac5e06fb444f83ec6015f088f3f78d7712c10e48f26d7be74"},{"item_id":"pilot-serf:year-1857","source_learning_sha256":"7549ad551ac97259a9b660c209f999d7346c9ca7a324aa939b295dcbb5b98307","source_item_sha256":"e4965947efd70e361261a83aa5f82788191323a92a6f7ee5e30b99bd24adf87e"},{"item_id":"pilot-serf:year-1858","source_learning_sha256":"e09a80514ede19342b43a8957ee491284c5a6312adf301b3fc750c0c8a90e3d3","source_item_sha256":"5919b6e2a3ca67380107032d5d8893513f44caa6cd28f136da8664dbf53129c7"},{"item_id":"pilot-serf:year-1859","source_learning_sha256":"73c5287d4665ee1412e8abfa3b3bbaee5e07ec955913470cebc61165cfc3ef77","source_item_sha256":"bffd0b071513134af5ea81cca4d19e9999242ea33f509f36115b7c4211b76979"}],"source_sections":[{"heading":"Австрийские преобразования 1848 года","text":"Учебник истории России называет общий период — середину XIX века. Дополнительный учебник всеобщей истории описывает реформу 1848 года, а публикация парламента Австрии уточняет санкционирование закона 7 сентября. До преобразования положение крестьян по землям империи различалось: в немецких провинциях сохранялись оброки при личной свободе, в восточных — личная зависимость и барщина.","utf8_sha256":"80b105545d3e771ef4e838274c6b66ff07230740c177f43894e081281bd90eda"},{"heading":"Сравнение по трём признакам","text":"По личному положению оба преобразования устраняли зависимость от помещика. По земельным обязательствам в Австрии закон отменял повинности и различал требования с компенсацией и без неё; в России после личного освобождения временнообязанные продолжали нести повинности до перехода на выкуп. По участию государства австрийская схема компенсации распределяла капитализированную сумму повинностей: треть списывалась, треть платил крестьянин, треть — государство. В российской учебниковой схеме государство предоставляло выкупную ссуду, которую крестьяне затем погашали; её нельзя считать безвозвратной оплатой государством крестьянской доли.","utf8_sha256":"be7a6c356044d5ad41d98f2d893af8b26f9b9b28849d1e4ccfd83fb00e3bae9c"},{"heading":"Вывод и границы сравнения","text":"Общее направление — прекращение личной зависимости при преобразовании земельных отношений. Различались сроки, сохранение повинностей на переходном этапе и характер государственной финансовой помощи. Схему австрийских земель нельзя переносить на всю империю без оговорок: учебник отдельно описывает венгерские меры. В исходной цитате сказано о рыночной стоимости земли; официальный парламентский разбор точнее называет капитализированную сумму повинностей. Цитата сохранена, пересказ разграничивает эти понятия.","utf8_sha256":"204f1d5fed4753639d7d612a95f80436be3dde1aba8f04fbef14995bb457e03f"}],"additional_saved_quotes":[{"sourceKey":"austria131","kind":"Фрагмент источника","sourceType":"external","sourceTitle":"Всеобщая история. 9 класс. § 11","sourceUrl":"https://drive.google.com/file/d/1RuUP3xZAiVq3OTL_UZE33_7_4EkDEZVB/view","page":131,"section":"Всеобщая история. 9 класс. § 11","quote":"В немецких провинциях крестьяне пользовались личной свободой и платили оброк, в восточных провинциях сохранялись личная зависимость и барщина."},{"sourceKey":"austria132","kind":"Фрагмент источника","sourceType":"external","sourceTitle":"Всеобщая история. История Нового времени. XIX — начало XX в. 9 класс. § 11","sourceUrl":"https://drive.google.com/file/d/1RuUP3xZAiVq3OTL_UZE33_7_4EkDEZVB/view","page":132,"section":"Всеобщая история. История Нового времени. XIX — начало XX в. 9 класс. § 11","quote":"В августе 1848 г. парламент разработал компромиссный закон: земля выкупалась по рыночной стоимости, но сам крестьянин выплачивал лишь треть, другую треть — государство, а от выплаты оставшейся трети помещик по закону отказывался."}]}};const a=window.CARD_REVIEWED_APPLICATIONS.answers;for(const k of Object.keys(p)){if(a[k])throw new Error("Unexpected accepted-answer overwrite "+k);}Object.assign(a,p);})();